const savedVersions=new Map<string,string>();
let mutationQueue:Promise<unknown>=Promise.resolve();
export const api = async (name:string,...args:unknown[]) => {
  if (!window.pywebview?.api?.[name]) throw new Error("Desktop bridge is not ready.");
  const call=async()=>{
    const payload=args[0] as Draft|undefined;
    if((name==='save_draft'||name==='submit')&&payload?.draft_id&&savedVersions.has(payload.draft_id)){args[0]={...payload,updated_at:savedVersions.get(payload.draft_id)}}
    const result=await window.pywebview!.api[name](...args);
    if(result?.draft?.draft_id)savedVersions.set(result.draft.draft_id,result.draft.updated_at);
    if(result?.draft_id)savedVersions.set(result.draft_id,result.updated_at);
    return result;
  };
  if(["save_draft","submit","approve","approve_percent","record_po","create_revision","reject","delete_draft","set_archived"].includes(name)){const result=mutationQueue.then(call);mutationQueue=result.catch(()=>undefined);return result}
  return call();
};
const n=(v:unknown)=>Number(String(v??0).replace(/,/g,""))||0;
export const money=(v:number,currency="PHP")=>new Intl.NumberFormat("en-PH",{style:"currency",currency,minimumFractionDigits:2}).format(v);
const decimalText=(v:number,maxDecimals=8)=>Number(v.toFixed(maxDecimals)).toString();
const percentFromRate=(v:unknown)=>decimalText(n(v)*100,6);
const rateFromPercent=(v:unknown)=>decimalText(n(v)/100,8);
const quantityTotal=(v:number)=>new Intl.NumberFormat("en-PH",{maximumFractionDigits:6}).format(Number(v.toFixed(6)));
const statusLabel=(s:string)=>({RETURNED_FOR_CORRECTION:"Returned for correction",QUOTATION_DRAFT:"Draft",RFQ_RECEIVED:"RFQ received",PENDING_INTERNAL_APPROVAL:"Pending internal approval",INTERNALLY_APPROVED:"Internally approved",CUSTOMER_PO_PARTIAL:"Partial customer PO",CUSTOMER_PO_ACCEPTED:"Customer PO accepted"}[s]||s);
