const blankItem=(number:number):Item=>({item_no:String(number),description:"",uom:"PC",quantity:"1",supplier_options:[],selected_supplier_id:"",macrotech_offer:"",quoted_unit_vat_ex:"0",macrotech_delivery:"",manual_offer:"",manual_unit_vat_ex:"0",manual_delivery:"",po_accepted:false,accepted_quantity:"0"});
const clone=<T,>(x:T):T=>structuredClone(x);

export function itemCalc(item:Item){
  const supplier=item.supplier_options.find(x=>x.id===item.selected_supplier_id);
  if(!supplier)return{unit:0,vatEx:0,vatIn:0,suggestedUnit:0,landed:0};
  const foreign=n(item.quantity)*n(supplier.unit_price)+n(supplier.freight_cost)+n(supplier.packing_cost)+n(supplier.bank_charges)+n(supplier.other_charges);
  let landed=0;
  if(supplier.cost_basis_mode==="LOCAL") landed=foreign;
  else {
    const subtotal=(foreign*n(supplier.forex_rate))*(1+n(supplier.duty_rate));
    const calculated=subtotal*(1+n(supplier.safety_factor_rate));
    landed=supplier.cost_basis_mode==="OVERRIDE"&&n(supplier.cost_basis_override)>0?n(supplier.cost_basis_override):calculated;
  }
  const unit=n(item.quantity)?(landed*n(supplier.markup_multiplier)/1.12)/n(item.quantity):0;
  const vatEx=unit*n(item.quantity);
  return{unit,vatEx,vatIn:vatEx*1.12,suggestedUnit:unit,landed};
}

export function draftTotals(draft:Draft){
  const snapshot=draft.commercial_snapshot||draft.approval_snapshot||draft.submitted_snapshot;
  if(snapshot?.grand_total_before_discount!==undefined)return{subtotal:n(snapshot.subtotal_vat_ex),vat:n(snapshot.vat),total:n(snapshot.grand_total_before_discount),discount:n(snapshot.discount),final:n(snapshot.final_total)};
  const subtotal=draft.items.reduce((sum,x)=>sum+itemCalc(x).vatEx,0),vat=subtotal*.12,total=subtotal+vat,discount=draft.discount_status==='APPROVED'?n(draft.discount_amount):0;
  return{subtotal,vat,total,discount,final:Math.max(0,total-discount)};
}

function snapshotLine(draft:Draft,itemNo:string){
  const snapshot=draft.commercial_snapshot||draft.approval_snapshot||draft.submitted_snapshot;
  return snapshot?.lines?.find(line=>String(line.item_no)===String(itemNo));
}

function acceptedLineValue(draft:Draft,item:Item,acceptedQuantity:number){
  const line=snapshotLine(draft,item.item_no),quotedQuantity=n(item.quantity);
  if(line&&quotedQuantity>0)return n(line.line_vat_in)*(acceptedQuantity/quotedQuantity);
  return itemCalc(item).unit*acceptedQuantity*1.12;
}

const tokenise=(value:string)=>String(value||"").toLowerCase().match(/[a-z0-9]+(?:[./-][a-z0-9]+)*(?:["']|mm|cm|in)?/g)||[];
function similarityDifference(item:Item, peers:Item[]){
  const a=tokenise(item.description); if(a.length<2)return "";
  let best:{score:number;other:Item}|null=null;
  for(const other of peers){
    if(other===item||!other.description)continue;
    const b=tokenise(other.description); const A=new Set(a),B=new Set(b);
    const common=[...A].filter(x=>B.has(x)).length; const union=new Set([...A,...B]).size||1;
    const score=common/union; if(score>=.55&&(!best||score>best.score))best={score,other};
  }
  if(!best)return "";
  const b=tokenise(best.other.description), B=new Set(b), A=new Set(a);
  const mine=a.filter(x=>!B.has(x)); const theirs=b.filter(x=>!A.has(x));
  if(!mine.length&&!theirs.length)return "";
  const left=mine.slice(0,3).join(" · ")||"same"; const right=theirs.slice(0,3).join(" · ")||"same";
  return `Difference vs Item ${best.other.item_no||"?"}: ${left} ↔ ${right}`;
}

function Field({label,value,onChange,type="text",wide=false,disabled=false,placeholder="",textarea=false,options}:{label:string;value:string;onChange:(v:string)=>void;type?:string;wide?:boolean;disabled?:boolean;placeholder?:string;textarea?:boolean;options?:{value:string;label:string}[]}){
  return <div className={`field ${wide?"wide":""}`}><label>{label}</label>{textarea?<textarea value={value??""} placeholder={placeholder} disabled={disabled} onChange={e=>onChange(e.target.value)}/>:options?<select value={value??""} disabled={disabled} onChange={e=>onChange(e.target.value)}>{options.map(x=><option key={x.value} value={x.value}>{x.label}</option>)}</select>:<input type={type} value={value??""} placeholder={placeholder} disabled={disabled} onChange={e=>onChange(e.target.value)}/>}</div>;
}

function MoneyField({label,value,currency,onChange,disabled=false}:{label:string;value:string;currency:string;onChange:(v:string)=>void;disabled?:boolean}){
  const symbol=currency==="USD"?"$":currency==="EUR"?"€":"₱";
  return <div className="field"><label>{label}</label><div className="money-input"><span>{symbol}</span><input type="number" min="0" step="0.01" value={value} disabled={disabled} onChange={e=>onChange(e.target.value)}/></div><small className="money-preview">{money(n(value),currency)}</small></div>;
}

function CustomerDirectoryFields({customer,buyer,buyerEmail,billingAddress,deliveryAddress,tin,directory,disabled,onChange,onRequest}:{customer:string;buyer:string;buyerEmail:string;billingAddress:string;deliveryAddress:string;tin:string;directory:CustomerCompany[];disabled:boolean;onChange:(value:{customer:string;buyer:string;buyerEmail:string;billingAddress:string;deliveryAddress:string;tin:string})=>void;onRequest:(kind:string,company:string,contact:string)=>void}){
  const company=directory.find(x=>x.code.toLowerCase()===customer.trim().toLowerCase());
  const setCustomer=(value:string)=>{
    const match=directory.find(x=>x.code.toLowerCase()===value.trim().toLowerCase());
    const contact=match?.contacts.length===1?match.contacts[0]:undefined;
    onChange({customer:match?.code||value,buyer:contact?.name||contact?.raw||"",buyerEmail:contact?.email||"",billingAddress:match?.billing_address||"",deliveryAddress:match?.delivery_address||"",tin:match?.tin||""});
  };
  const setBuyer=(value:string)=>{const match=company?.contacts.find(x=>x.name===value||x.raw===value||x.email===value);onChange({customer,buyer:match?.name||value,buyerEmail:match?.email||buyerEmail,billingAddress,deliveryAddress,tin})};
  const update=(changes:Partial<{customer:string;buyer:string;buyerEmail:string;billingAddress:string;deliveryAddress:string;tin:string}>)=>onChange({customer,buyer,buyerEmail,billingAddress,deliveryAddress,tin,...changes});
  const contactHelp=company
    ? company.contacts.length===1
      ? "The only known contact was filled automatically. You can still enter a new contact."
      : `${company.contacts.length} known contacts for ${company.code}. Choose the correct buyer for this RFQ.`
    : customer
      ? "Select a matching company or keep typing to enter a new customer."
      : "Start typing a company code or name. Example: GNP lists GNPD and GNPK.";
  return <section className="customer-directory-card wide" aria-label="Customer and associated buyer information"><div className="customer-parent"><div className="field wide directory-field"><label>Company / Customer</label><input list="customer-directory-options" value={customer} disabled={disabled} placeholder="Start typing a company code or name" onChange={e=>setCustomer(e.target.value)}/><datalist id="customer-directory-options">{directory.map(x=><option key={x.id} value={x.code}>{x.contacts.length} contact{x.contacts.length===1?"":"s"}</option>)}</datalist><small className="directory-help">{contactHelp}</small></div><div className="customer-address-grid"><Field label="Billing address" value={billingAddress} disabled={disabled} wide onChange={v=>update({billingAddress:v})}/><Field label="Delivery address" value={deliveryAddress} disabled={disabled} wide onChange={v=>update({deliveryAddress:v})}/><Field label="Customer TIN" value={tin} disabled={disabled} onChange={v=>update({tin:v})}/></div></div><div className="customer-contact-child"><div className="customer-link" aria-hidden="true"/><div className="fields"><div className="field"><label>Buyer / Contact</label><input list="customer-contact-options" value={buyer} disabled={disabled} placeholder={company?`Select a ${company.code} buyer or enter a new contact`:"Select the company first, or enter a contact manually"} onChange={e=>setBuyer(e.target.value)}/><datalist id="customer-contact-options">{(company?.contacts||[]).map(x=><option key={x.id} value={x.name||x.raw}>{x.email}</option>)}</datalist></div><Field label="Email" value={buyerEmail} disabled={disabled} type="email" onChange={v=>update({buyerEmail:v})}/></div><small className="directory-help">{company?`This buyer and email are associated with ${company.code}.`:"Buyer suggestions become company-specific after an exact company match."}</small>{!disabled&&<div className="directory-actions"><button className="ghost" onClick={()=>onRequest("COMPANY",customer,"")}>Request new company</button><button className="ghost" onClick={()=>onRequest("CONTACT",customer,`${buyer}${buyerEmail?` <${buyerEmail}>`:""}`)}>Request new contact</button></div>}</div></section>;
}

